// frontend/src/Board.jsx  (full version)
import { useEffect, useState } from "react";
import { api } from "./api.js";

const FILTERS = { all: "", active: "?status=active", done: "?status=done" };

export default function Board({ token, onLogout }) {
  const [tasks, setTasks] = useState([]);
  const [show, setShow] = useState("all");
  const [title, setTitle] = useState("");
  const [due, setDue] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  function fail(err) {
    if (err.status === 401) onLogout();
    else setError(err.message);
  }

  useEffect(() => {
    setLoading(true); setError("");
    api("/tasks/" + FILTERS[show], { token }).then(setTasks).catch(fail).finally(() => setLoading(false));
  }, [show, token]);

  async function add(e) {
    e.preventDefault();
    try {
      const task = await api("/tasks/", { method: "POST", token, body: { title, due: due || null } });
      if (show !== "done") setTasks([task, ...tasks]);
      setTitle(""); setDue(""); setError("");
    } catch (err) { fail(err); }
  }

  async function toggle(task) {
    try {
      const saved = await api("/tasks/" + task.id + "/", { method: "PATCH", token, body: { done: !task.done } });
      setTasks(show === "all" ? tasks.map(t => (t.id === task.id ? saved : t)) : tasks.filter(t => t.id !== task.id));
    } catch (err) { fail(err); }
  }

  async function remove(task) {
    if (!confirm("Delete \"" + task.title + "\"?")) return;
    try {
      await api("/tasks/" + task.id + "/", { method: "DELETE", token });
      setTasks(tasks.filter(t => t.id !== task.id));
    } catch (err) { fail(err); }
  }

  const left = tasks.filter(t => !t.done).length;

  return (
    <div className="board">
      <header><h2>My tasks</h2><button onClick={onLogout}>Sign out</button></header>
      <form onSubmit={add}>
        <input value={title} onChange={e => setTitle(e.target.value)} placeholder="What needs doing?" />
        <input type="date" value={due} onChange={e => setDue(e.target.value)} />
        <button disabled={!title.trim()}>Add</button>
      </form>
      <nav>
        {Object.keys(FILTERS).map(f => (
          <button key={f} className={show === f ? "on" : ""} onClick={() => setShow(f)}>{f}</button>
        ))}
        {show === "all" && <span>{left} left</span>}
      </nav>
      {error && <p className="error">{error}</p>}
      {loading ? <p>Loading…</p> : (
        <ul>
          {tasks.map(t => (
            <li key={t.id} className={t.done ? "done" : ""}>
              <input type="checkbox" checked={t.done} onChange={() => toggle(t)} />
              <span>{t.title}</span>
              {t.due && <small>{t.due}</small>}
              <button onClick={() => remove(t)} aria-label="Delete">✕</button>
            </li>
          ))}
          {tasks.length === 0 && <li className="empty">Nothing here yet.</li>}
        </ul>
      )}
    </div>
  );
}

